use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

const SYSTEM: &str =
    "You are a customer-support agent. Answer the user's question using only the \
     provided knowledge. If you need to look something up, request the lookup tool.";

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

fn build_prompt(intent: Intent, question: &str, knowledge: &[String]) -> String {
    let mut prompt = String::new();
    prompt.push_str("Intent: ");
    prompt.push_str(intent_label(intent));
    prompt.push('\n');

    prompt.push_str("Knowledge:\n");
    if knowledge.is_empty() {
        prompt.push_str("(none)\n");
    } else {
        for entry in knowledge {
            prompt.push_str("- ");
            prompt.push_str(entry);
            prompt.push('\n');
        }
    }

    prompt.push_str("Question: ");
    prompt.push_str(question);
    prompt
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        let ConversationContext {
            intent,
            question,
            knowledge,
        } = ctx;

        let prompt = build_prompt(intent, &question, &knowledge);

        // First round: ask the model. It either answers, or asks for a tool.
        match tool_llm::generate(SYSTEM, &prompt) {
            Reply::Text(text) => ResponseResult::Ok(AgentResponse { text }),
            Reply::Call(request) => {
                // The only tool this node holds is `lookup` (kb-read). Any other
                // requested tool is authority the node was not granted.
                if request.tool != "lookup" {
                    return ResponseResult::Error(LlmError {
                        message: format!("unsupported tool requested: {}", request.tool),
                    });
                }

                let results = kb_read::lookup(&request.query);

                // Second round: feed the lookup results back and get a final answer.
                let mut followup = prompt;
                followup.push_str("\nLookup results:\n");
                if results.is_empty() {
                    followup.push_str("(no results)\n");
                } else {
                    for entry in &results {
                        followup.push_str("- ");
                        followup.push_str(entry);
                        followup.push('\n');
                    }
                }

                match tool_llm::generate(SYSTEM, &followup) {
                    Reply::Text(text) => ResponseResult::Ok(AgentResponse { text }),
                    Reply::Call(_) => ResponseResult::Error(LlmError {
                        message: "model requested a further tool call after lookup".to_string(),
                    }),
                }
            }
        }
    }
}

export!(Node);
```

